examples.setup:
@Environment(\.monarchTheme) private var theme
@State private var hidden: Set<String> = []
@State private var period = "6m"

examples.code:
MonarchChartFrame(
    "Revenue and costs",
    description: "Monthly, in dollars",
    table: MonarchChartTable(
        categoryTitle: "Month",
        categories: ["Jan", "Feb"],
        series: [
            MonarchChartTableSeries("Revenue", values: [1200, 1450]),
            MonarchChartTableSeries("Costs", values: [900, 950]),
        ]
    ),
    legend: [
        MonarchChartLegendItem("revenue", label: "Revenue"),
        MonarchChartLegendItem("costs", label: "Costs"),
    ],
    hiddenSeries: $hidden,
    content: {
        Chart {
            BarMark(x: .value("Month", "Jan"), y: .value("Revenue", 1200))
            BarMark(x: .value("Month", "Feb"), y: .value("Revenue", 1450))
        }
        .foregroundStyle(theme.colors.data1)
    },
    actions: {
        Picker("Period", selection: $period) {
            Text("6 months").tag("6m")
            Text("1 year").tag("1y")
        }
        .pickerStyle(.menu)
    }
)

VStack {
    MonarchChartFrame("Signups", status: .loading, height: 120) { EmptyView() }
    MonarchChartFrame("Signups", status: .empty, emptyMessage: "Signups appear after the first registration.") { EmptyView() }
    MonarchChartFrame("Signups", status: .error, height: 120, onRetry: { attempts += 1 }, content: { EmptyView() })
}

MonarchChartFrame(
    "Risk",
    table: MonarchChartTable(
        categoryTitle: "Region",
        categories: ["North", "South"],
        series: [
            MonarchChartTableSeries("Score", values: [12, 30]),
            MonarchChartTableSeries("Band", texts: ["Low", "High"]),
        ]
    ),
    height: 120
) {
    MonarchSparkline([12, 30])
}
